const order = $input.item.json;
const customerName = (order.customer && order.customer.full_name) ? order.customer.full_name : 'عميل';
const itemsSummary = (Array.isArray(order.items) && order.items.length > 0)
  ? order.items.map(it => it.variant_name || it.sku || 'منتج').join('، ')
  : 'طلب';
const amount = (order.total_amount !== null && order.total_amount !== undefined) ? order.total_amount : '';

const title = 'طلب جديد بانتظار المراجعة';
const body = `${customerName} — ${itemsSummary}${amount !== '' ? ' — ' + amount : ''}`;

return [{ json: { order_id: order.id, title, body } }];
